#include "app/events/domain_event_bus.hpp"
#include "support/check.hpp"
#include <stdexcept>
struct Approved{int id;};
int main(){namespace t=squiflow::testing;using namespace squiflow::app;DomainEventBus bus;int first=0,second=0;bus.subscribe<Approved>([&](const auto&,const Approved&e){first=e.id;return Result<void,DomainError>::success();});bus.subscribe<Approved>([&](const auto&,const Approved&e){second=e.id;return Result<void,DomainError>::success();});auto before=bus.publish(EventMetadata{},Approved{1});t::check(!before,"publishing before freeze refused");bus.freeze();PostCommitEvents batch;batch.add([&]{return bus.publish(EventMetadata{"e","c","",1},Approved{7});});t::check(first==0&&second==0,"events wait for commit");t::check(batch.commit()&&first==7&&second==7,"subscribers run deterministically after commit");PostCommitEvents rolled;rolled.add([&]{first=9;return Result<void,DomainError>::success();});rolled.rollback();t::check(first==7,"rollback discards events");auto twice=batch.commit();t::check(!twice,"batch cannot commit twice");bool late=false;try{bus.subscribe<Approved>([](const auto&,const auto&){return Result<void,DomainError>::success();});}catch(const std::logic_error&){late=true;}t::check(late,"subscriptions freeze at startup");return t::report();}
